let ledgerSearch='',ledgerFilter='all';
const expenseCategories={other:'অন্যান্য',food:'খাবার',travel:'যাতায়াত',shopping:'কেনাকাটা',bills:'বিল',health:'চিকিৎসা',business:'ব্যবসা'};
function validFeatureData(d){if(!d||!Array.isArray(d.people)||!Array.isArray(d.entries))return false;const categories=['other','food','travel','shopping','bills','health','business'],record=v=>v&&typeof v==='object'&&!Array.isArray(v),date=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v+'T12:00:00Z'))&&new Date(v+'T12:00:00Z').toISOString().slice(0,10)===v;return d.entries.every(e=>e.category===undefined||categories.includes(e.category))&&(d.settings==null||(record(d.settings)&&(d.settings.theme===undefined||['light','dark','system'].includes(d.settings.theme))&&(d.settings.currency===undefined||['BDT','USD','EUR','GBP'].includes(d.settings.currency))&&(d.settings.budgets===undefined||(record(d.settings.budgets)&&Object.entries(d.settings.budgets).every(([month,value])=>/^\d{4}-(0[1-9]|1[0-2])$/.test(month)&&Number.isFinite(value)&&value>=0&&value<=999999999)))))&&(d.reminders===undefined||(Array.isArray(d.reminders)&&d.reminders.length<=10000&&new Set(d.reminders.map(r=>r.id)).size===d.reminders.length&&d.reminders.every(r=>typeof r.id==='string'&&d.people.some(p=>p.id===r.person)&&date(r.date)&&/^([01]\d|2[0-3]):[0-5]\d$/.test(r.time)&&typeof r.done==='boolean'&&(r.description===undefined||(typeof r.description==='string'&&r.description.length<=500)))))}

function featureText(text){return typeof translateUI==='function'?translateUI(text):text}
function categorySelect(value='other'){return '<label>খরচের খাত<select name="category">'+Object.entries(expenseCategories).map(([key,name])=>'<option value="'+key+'"'+(key===value?' selected':'')+'>'+name+'</option>').join('')+'</select></label>'}
function advancedMatches(item){if(item.type==='expense')return ['all','expenses'].includes(ledgerFilter)&&(!ledgerSearch||(item.latest.note||'').toLowerCase().includes(ledgerSearch));const p=db.people.find(p=>p.id===item.person),net=Math.round(netBalance(p)*100);return (!ledgerSearch||(p.name+' '+p.phone).toLowerCase().includes(ledgerSearch))&&(ledgerFilter==='all'||ledgerFilter==='receivable'&&net>0||ledgerFilter==='payable'&&net<0||ledgerFilter==='settled'&&net===0)}
function searchTools(){return '<div class="ledger-search-tools"><input id="ledger-search" type="search" placeholder="নাম বা নম্বর দিয়ে খুঁজুন" value="'+esc(ledgerSearch)+'"><select id="ledger-filter" aria-label="ফিল্টার">'+[['all','সব'],['receivable','পাবো'],['payable','দেবো'],['settled','হিসাব সমান'],['expenses','খরচ']].map(([key,name])=>'<option value="'+key+'"'+(key===ledgerFilter?' selected':'')+'>'+name+'</option>').join('')+'</select></div>'}
function expenseBreakdown(entries){const totals={};for(const e of entries)if(e.kind==='expense')totals[e.category||'other']=(totals[e.category||'other']||0)+e.amount;return '<div class="expense-breakdown">'+Object.entries(totals).map(([key,total])=>'<div><span>'+expenseCategories[key]+'</span><strong>'+money(total)+'</strong></div>').join('')+'</div>'}
function budgetState(month=today().slice(0,7)){const limit=Number(db.settings?.budgets?.[month]||0),spent=db.entries.filter(e=>e.kind==='expense'&&e.date.startsWith(month)).reduce((sum,e)=>sum+e.amount,0);return {month,limit,spent,percent:limit?Math.min(100,Math.round(spent/limit*100)):0}}
function budgetOverview(){const b=budgetState();if(!b.limit)return '';return '<section class="budget-overview"><div class="feature-title"><h2>মাসিক বাজেট</h2><button data-feature="budget">পরিবর্তন</button></div><p><span>'+money(b.spent)+'</span> / <span>'+(b.limit?money(b.limit):featureText('বাজেট নেই'))+'</span></p>'+(b.limit?'<progress max="100" value="'+b.percent+'"></progress><small>'+(b.spent>b.limit?'বাজেট অতিক্রম করেছে':b.percent>=80?'বাজেটের সীমার কাছাকাছি':'এই মাসের খরচ')+'</small>':'')+'</section>'}
function advancedProfileView(){const icon=name=>name==='language'?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/></svg>':name==='device'&&typeof deviceAccessIcon==='function'?deviceAccessIcon():typeof profileIcon==='function'?profileIcon(name):'';return '<section class="profile-account-tools"><h2>হিসাবের সুবিধা</h2><div class="feature-menu">'+[...(typeof accountRole!=='undefined'&&accountRole==='admin'?[['admin','shield','অ্যাডমিন প্যানেল']]:[]),['reminders','bell','রিমাইন্ডার'],['budget','budget','মাসিক বাজেট'],['currency','currency','মুদ্রা'],['theme','theme','থিম'],['language','language','ভাষা'],['device','device','ডিভাইস দিয়ে লগইন'],['trash','trash','ট্র্যাশ']].map(([key,symbol,text])=>'<button class="profile-setting-row" data-feature="'+key+'"><span class="profile-row-icon">'+icon(symbol)+'</span><span>'+text+'</span>'+(key==='currency'?'<span class="profile-currency-badge">'+esc(currencySymbol())+'</span>':'')+icon('chevron')+'</button>').join('')+'</div></section>'}

function featureDialog(title,content){const dialog=document.createElement('dialog');dialog.className='transaction-dialog feature-dialog';dialog.innerHTML='<div class="dialog-top"><span>'+esc(title)+'</span><button type="button" aria-label="পপআপ বন্ধ করুন">✕</button></div><section>'+content+'</section>';dialog.querySelector('.dialog-top button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());$('#app').append(dialog);dialog.showModal();return dialog}
function featureError(dialog,error){let box=dialog.querySelector('.feature-error');if(!box){box=document.createElement('p');box.className='feature-error danger';dialog.querySelector('section').append(box)}box.textContent=error.message}
function openBudget(){const b=budgetState(),dialog=featureDialog(featureText('মাসিক বাজেট'),'<form><label>মাস বাছুন<input type="month" name="month" value="'+b.month+'" required></label><label>বাজেট<input type="number" name="limit" min="0" max="999999999" step="0.01" value="'+b.limit+'" required></label><button class="primary">সংরক্ষণ করুন</button></form>');const form=dialog.querySelector('form');form.elements.month.onchange=()=>{form.elements.limit.value=db.settings?.budgets?.[form.elements.month.value]||0};form.onsubmit=async e=>{e.preventDefault();const data=new FormData(form),month=data.get('month'),limit=Number(data.get('limit'));if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month)||!Number.isFinite(limit)||limit<0)return;await commit(()=>{db.settings=db.settings||{};db.settings.budgets=db.settings.budgets||{};db.settings.budgets[month]=limit})}}
function auditSnapshotView(record){if(!record)return '<p class="muted">কোনো তথ্য নেই।</p>';return '<div class="audit-values">'+(record.name?'<p data-user-text>'+esc(record.name)+'</p>':'')+(record.phone?'<p data-user-text>'+esc(record.phone)+'</p>':'')+(record.kind?'<p>'+featureText(labels[record.kind]||record.kind)+'</p>':'')+(Number.isFinite(record.amount)?'<strong>'+money(record.amount)+'</strong>':'')+(record.date?'<small>'+esc(record.date)+(record.time?' · '+esc(displayTime12(record.time)):'')+'</small>':'')+(record.note?'<p data-user-text>'+esc(record.note)+'</p>':'')+(record.photo?'<small>ছবি সংযুক্ত আছে</small>':'')+'</div>'}
function savedRecordMarkup(kind,item){const p=item.payload,title=p.person?.name||p.entry?.note||p.after?.name||p.before?.name||p.after?.note||p.before?.note||featureText(p.type==='person'?'ব্যক্তি':'লেনদেন');return '<article class="feature-record"><strong data-user-text>'+esc(title)+'</strong><small>'+esc(item.at)+'</small>'+(kind==='trash'?'<button data-restore="'+esc(item.id)+'">ফিরিয়ে আনুন</button>':'<p>'+featureText(p.action==='added'?'যোগ করা হয়েছে':p.action==='edited'?'পরিবর্তন করা হয়েছে':p.action==='restored'?'ফিরিয়ে আনা হয়েছে':'ডিলিট করা হয়েছে')+'</p><details><summary>বিস্তারিত</summary><h4>আগের তথ্য</h4>'+auditSnapshotView(p.before)+'<h4>নতুন তথ্য</h4>'+auditSnapshotView(p.after)+'</details>')+'</article>'}
async function openSavedRecords(kind){const dialog=featureDialog(featureText(kind==='trash'?'ট্র্যাশ':'পরিবর্তনের ইতিহাস'),'<div class="saved-records-list"></div><button class="records-next">আরও দেখুন</button>');const list=dialog.querySelector('.saved-records-list'),more=dialog.querySelector('.records-next');let cursor=null,count=0;const load=async()=>{more.disabled=true;try{const result=await accountAPI((kind==='trash'?'trash':'history')+(cursor?'?cursor='+encodeURIComponent(cursor):''));count+=result.items.length;list.insertAdjacentHTML('beforeend',result.items.map(item=>savedRecordMarkup(kind,item)).join(''));if(!count)list.innerHTML='<p class="muted">কোনো তথ্য নেই।</p>';cursor=result.next;more.hidden=!cursor;list.querySelectorAll('[data-restore]').forEach(button=>button.onclick=async()=>{if(accountBusy)return;if(offlineState?.pending)return featureError(dialog,Error(featureText('আগে অফলাইন তথ্য সিঙ্ক করুন।')));accountBusy=true;button.disabled=true;try{const restored=await accountAPI('restore','POST',{id:button.dataset.restore,revision:accountRevision});db=restored.data;accountRevision=restored.revision;await rememberAccount();render()}catch(error){featureError(dialog,error);button.disabled=false}finally{accountBusy=false}})}catch(error){featureError(dialog,error)}finally{more.disabled=false}};more.onclick=load;await load()}

function reminderNotificationText(r){return [personName(r.person),r.description].filter(Boolean).join(' — ')}
function reminderCards(){return (db.reminders||[]).slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(r=>'<article class="reminder-card'+(r.done?' is-complete':'')+'"><div class="reminder-card-top"><strong data-user-text>'+esc(personName(r.person))+'</strong><span class="reminder-status">'+featureText(r.done?'সম্পন্ন':'অপেক্ষমাণ')+'</span></div>'+(r.description?'<p data-user-text>'+esc(r.description)+'</p>':'')+'<small>'+esc(r.date)+' · '+esc(displayTime12(r.time))+'</small><div class="reminder-card-actions"><button type="button" data-reminder-done="'+esc(r.id)+'"'+(r.done?' disabled':'')+'>'+featureText(r.done?'সম্পন্ন':'সম্পন্ন করুন')+'</button><button type="button" data-reminder-delete="'+esc(r.id)+'">ডিলিট</button></div></article>').join('')}
async function enableReminderNotifications(dialog){const button=dialog.querySelector('#enable-notifications'),status=dialog.querySelector('#reminder-notification-status');button.disabled=true;try{if(!('Notification'in window)||!('PushManager'in window)||!navigator.serviceWorker)throw Error(featureText('নোটিফিকেশনের জন্য সমর্থিত ব্রাউজারে HTTPS লিংক খুলুন। iPhone-এ Home Screen থেকে অ্যাপটি খুলুন।'));const permission=await Notification.requestPermission();if(permission!=='granted')throw Error(featureText('নোটিফিকেশনের অনুমতি দিন। ফোনের সেটিংস থেকে অনুমতি বদলাতে পারবেন।'));const config=await accountAPI('notifications/config');if(!config.enabled)throw Error(featureText('ফোনের নোটিফিকেশনের জন্য HTTPS সার্ভার চালু করতে হবে।'));const registration=await navigator.serviceWorker.ready;let subscription=await registration.pushManager.getSubscription();if(!subscription){const value=config.publicKey.replace(/-/g,'+').replace(/_/g,'/'),raw=atob(value+'='.repeat((4-value.length%4)%4));subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(raw,c=>c.charCodeAt(0))})}await accountAPI('notifications/subscribe','POST',{subscription:subscription.toJSON(),language:typeof uiLanguage==='string'?uiLanguage:'en'});status.textContent=featureText('ফোনের নোটিফিকেশন চালু হয়েছে।');status.className='reminder-permission-status is-enabled';button.textContent=featureText('নোটিফিকেশন চালু আছে')}catch(error){status.textContent=error.message;status.className='reminder-permission-status'}finally{button.disabled=false}}
function openReminders(){const icon=typeof profileIcon==='function'?profileIcon('bell'):'',dialog=featureDialog(featureText('রিমাইন্ডার'),'<div class="reminder-intro"><span>'+icon+'</span><div><h2>সময়মতো মনে করিয়ে দিন</h2><p>তারিখ, সময় ও প্রয়োজনীয় বিবরণ লিখুন</p></div></div><form id="reminder-form"><label>ব্যক্তি<select name="person" required>'+(!db.people.length?'<option value="">আগে একজন ব্যক্তিকে যোগ করুন</option>':db.people.map(p=>'<option value="'+esc(p.id)+'" data-user-text>'+esc(p.name)+'</option>').join(''))+'</select></label><div class="reminder-datetime"><label>তারিখ<input name="date" type="date" min="'+today()+'" value="'+today()+'" required></label><label>সময়<input name="time" type="time" required></label></div><label>বিবরণ<textarea name="description" rows="4" maxlength="500" placeholder="কী মনে করিয়ে দিতে হবে লিখুন"></textarea></label><p id="reminder-form-error" class="danger" role="alert"></p><button class="primary"'+(!db.people.length?' disabled':'')+'>রিমাইন্ডার সংরক্ষণ করুন</button></form><div class="reminder-permission"><span class="reminder-permission-icon">'+icon+'</span><div><h3>ফোনের নোটিফিকেশন</h3><p>অনুমতি দিলে নির্ধারিত সময়ে বিবরণসহ নোটিফিকেশন পাবেন।</p></div><button type="button" id="enable-notifications">নোটিফিকেশন চালু করুন</button><p id="reminder-notification-status" class="reminder-permission-status" role="status">HTTPS সার্ভার চালু থাকতে হবে। iPhone-এ অ্যাপটি Home Screen-এ যোগ করুন।</p></div><div class="reminder-list"><h3>সংরক্ষিত রিমাইন্ডার</h3>'+(reminderCards()||'<p class="reminder-empty">এখনও কোনো রিমাইন্ডার নেই।</p>')+'</div>');dialog.classList.add('reminders-dialog');dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),date=String(f.get('date')),time=String(f.get('time')),description=String(f.get('description')||'').trim(),person=f.get('person');if(!db.people.some(p=>p.id===person)||!Number.isFinite(Date.parse(date+'T'+time+':00+06:00'))||Date.parse(date+'T'+time+':00+06:00')<=Date.now()){dialog.querySelector('#reminder-form-error').textContent=featureText('ভবিষ্যতের সঠিক তারিখ ও সময় দিন।');return}await commit(()=>{db.reminders=db.reminders||[];db.reminders.push({id:id(),person,date,time,description,done:false})})};dialog.querySelector('#enable-notifications').onclick=()=>enableReminderNotifications(dialog);dialog.querySelectorAll('[data-reminder-done]').forEach(b=>b.onclick=()=>commit(()=>{db.reminders.find(r=>r.id===b.dataset.reminderDone).done=true}));dialog.querySelectorAll('[data-reminder-delete]').forEach(b=>b.onclick=()=>commit(()=>{db.reminders=db.reminders.filter(r=>r.id!==b.dataset.reminderDelete)}))}
const notifiedReminders=new Set();function checkReminders(){if(!accountPhone||typeof db==='undefined')return;const now=today()+' '+currentExpenseTime();for(const r of db.reminders||[]){const key=accountPhone+':'+r.id+':'+r.date+':'+r.time+':'+(r.description||'');if(r.done||r.date+' '+r.time>now||notifiedReminders.has(key))continue;notifiedReminders.add(key);const message=document.createElement('article');message.className='reminder-notice reminder-popup';message.setAttribute('role','alert');message.innerHTML='<div class="reminder-popup-heading"><strong>'+esc(featureText('রিমাইন্ডার'))+'</strong><button type="button" aria-label="'+esc(featureText('পপআপ বন্ধ করুন'))+'">✕</button></div><p data-user-text>'+esc(reminderNotificationText(r))+'</p><small>'+esc(r.date)+' · '+esc(displayTime12(r.time))+'</small>';message.querySelector('button').onclick=()=>message.remove();$('#app').prepend(message)}}

function statementText(personId){const p=db.people.find(p=>p.id===personId),entries=db.entries.filter(e=>e.person===personId),net=netBalance(p);return ['DailyTally',p.name,featureText(net>0?'মোট পাবো':net<0?'মোট দেবো':'হিসাব সমান')+': '+money(Math.abs(net)),...entries.slice(-10).map(e=>e.date+' · '+featureText(labels[e.kind])+' · '+money(e.amount)+(e.note?' · '+e.note:''))].join('\n')}
function whatsappLink(personId){const p=db.people.find(p=>p.id===personId);let phone=normalizePhone(p.phone);if(/^01\d{9}$/.test(phone))phone='88'+phone;return 'https://wa.me/'+(/^[1-9]\d{6,14}$/.test(phone)?phone:'')+'?text='+encodeURIComponent(statementText(personId))}

function addRecoveryLink(register){if(register)return;const button=document.createElement('button');button.type='button';button.className='forgot-password';button.textContent='পাসওয়ার্ড ভুলে গেছেন?';button.onclick=openEmailPasswordReset;document.querySelector('#auth-form').after(button)}
function featuresAfterRender(){if(typeof bindServerBackups==='function')bindServerBackups();window.DailyTallyTheme?.sync(db.settings?.theme||'system');bindReportFilters();const emailButton=$('#account-email-edit');if(emailButton)emailButton.onclick=openEmailSettings;const search=$('#ledger-search');if(search){const update=()=>{const container=$('#recent-ledgers-body');if(container){container.innerHTML=recentSummaryView();bindRecentSummaries()}};search.oninput=()=>{ledgerSearch=search.value.toLowerCase().trim();update()};$('#ledger-filter').onchange=e=>{ledgerFilter=e.target.value;update()}}document.querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>({admin:()=>{adminPersonalMode=false;render()},language:openLanguageSettings,device:openDeviceAccessSettings,theme:openThemeSettings,currency:openCurrency,budget:openBudget,reminders:openReminders,history:()=>openSavedRecords('history'),trash:()=>openSavedRecords('trash')}[b.dataset.feature])());checkReminders();renderSyncStatus?.()}
setInterval(checkReminders,15000);

const appCurrencies={BDT:{name:'বাংলাদেশি টাকা',symbol:'৳'},USD:{name:'মার্কিন ডলার',symbol:'$'},EUR:{name:'ইউরো',symbol:'€'},GBP:{name:'ব্রিটিশ পাউন্ড',symbol:'£'}};
function currencyCode(){return Object.hasOwn(appCurrencies,db.settings?.currency)?db.settings.currency:'BDT'}
function currencySymbol(){return appCurrencies[currencyCode()].symbol}
function openCurrency(){
 const selected=currencyCode(),current=appCurrencies[selected];
 const dialog=featureDialog(featureText('মুদ্রা'),'<p class="muted">মুদ্রার প্রতীক বাছুন</p><div class="currency-picker"><button type="button" class="currency-toggle" aria-expanded="false" aria-controls="currency-options"><span>'+esc(featureText(current.name))+'</span><span class="currency-option-end"><strong>'+current.symbol+'</strong><span aria-hidden="true">⌄</span></span></button><div id="currency-options" class="currency-options" role="listbox" aria-label="'+esc(featureText('মুদ্রা'))+'" hidden>'+Object.entries(appCurrencies).map(([code,c])=>'<button type="button" role="option" aria-selected="'+(code===selected)+'" data-currency="'+code+'"><span>'+esc(featureText(c.name))+'</span><strong>'+c.symbol+'</strong></button>').join('')+'</div></div><small class="currency-note">শুধু প্রতীক বদলাবে, টাকার পরিমাণ বদলাবে না।</small>');
 const toggle=dialog.querySelector('.currency-toggle'),list=dialog.querySelector('.currency-options'),options=[...list.querySelectorAll('[data-currency]')];
 const expand=()=>{list.hidden=false;toggle.setAttribute('aria-expanded','true');options.find(b=>b.dataset.currency===selected).focus()};
 toggle.onclick=()=>{if(list.hidden)expand();else{list.hidden=true;toggle.setAttribute('aria-expanded','false')}};
 toggle.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();expand()}};
 list.onkeydown=e=>{const index=options.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();options[e.key==='Home'?0:e.key==='End'?options.length-1:(index+(e.key==='ArrowDown'?1:-1)+options.length)%options.length].focus()}else if(e.key==='Escape'){e.preventDefault();e.stopPropagation();list.hidden=true;toggle.setAttribute('aria-expanded','false');toggle.focus()}};
 options.forEach(button=>button.onclick=async()=>{if(accountBusy)return;options.forEach(b=>b.disabled=true);try{const saved=await commit(()=>{db.settings=db.settings||{};db.settings.currency=button.dataset.currency});if(saved)dialog.close()}catch(error){featureError(dialog,error)}finally{options.forEach(b=>b.disabled=false)}});
}

if(typeof navigator!=='undefined'&&navigator.serviceWorker)navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type==='OPEN_REMINDERS'&&accountPhone)openReminders()});

async function restoreReminderNotifications(){try{if(typeof Notification==='undefined'||Notification.permission!=='granted'||!navigator.serviceWorker)return;const registration=await navigator.serviceWorker.getRegistration();const subscription=await registration?.pushManager?.getSubscription();if(subscription)await accountAPI('notifications/subscribe','POST',{subscription:subscription.toJSON(),language:typeof uiLanguage==='string'?uiLanguage:'en'})}catch{}}

let reportSearch='',reportFilter='all',reportExpenseCategory='all';
function reportEntryMatches(entry){if(entry.kind==='expense')return ['all','expenses'].includes(reportFilter)&&(reportFilter!=='expenses'||reportExpenseCategory==='all'||(entry.category||'other')===reportExpenseCategory)&&(!reportSearch||(entry.note||'').toLowerCase().includes(reportSearch));const person=db.people.find(p=>p.id===entry.person);if(!person)return reportFilter==='all'&&!reportSearch;const net=Math.round(netBalance(person)*100);return (!reportSearch||(person.name+' '+person.phone).toLowerCase().includes(reportSearch))&&(reportFilter==='all'||reportFilter==='receivable'&&net>0||reportFilter==='payable'&&net<0||reportFilter==='settled'&&net===0)}
function reportSearchTools(){return '<div class="ledger-search-tools report-search-tools"><input id="report-search" type="search" placeholder="নাম বা নম্বর দিয়ে খুঁজুন" value="'+esc(reportSearch)+'"><select id="report-filter" aria-label="রিপোর্টের ফিল্টার">'+[['all','সব'],['receivable','পাবো'],['payable','দেবো'],['settled','হিসাব সমান'],['expenses','খরচ']].map(([key,name])=>'<option value="'+key+'"'+(key===reportFilter?' selected':'')+'>'+name+'</option>').join('')+'</select></div><label id="report-expense-category-field"'+(reportFilter==='expenses'?'':' hidden')+'>খরচের খাত<select id="report-expense-category">'+[['all','সব খরচের খাত'],...Object.entries(expenseCategories)].map(([key,name])=>'<option value="'+key+'"'+(key===reportExpenseCategory?' selected':'')+'>'+name+'</option>').join('')+'</select></label>'}
function bindReportFilters(){const search=$('#report-search'),filter=$('#report-filter'),category=$('#report-expense-category'),categoryField=$('#report-expense-category-field');if(!search||!filter)return;const update=()=>{const people=$('#report-people-results'),records=$('#report');if(people)people.innerHTML=personReports();if(records)records.innerHTML=reportExpenseCaption()+rows(filteredReportEntries().slice().sort((a,b)=>b.date.localeCompare(a.date)));bindPersonReports()};search.oninput=()=>{reportSearch=search.value.toLowerCase().trim();update()};filter.onchange=()=>{reportFilter=filter.value;if(categoryField)categoryField.hidden=reportFilter!=='expenses';update()};if(category)category.onchange=()=>{reportExpenseCategory=Object.hasOwn(expenseCategories,category.value)?category.value:'all';update()}}

function openThemeSettings(){const current=['light','dark','system'].includes(db.settings?.theme)?db.settings.theme:'system',choices=[['light','লাইট মোড','হালকা ও পরিষ্কার'],['dark','ডার্ক মোড','চোখের আরামের জন্য গাঢ় রং'],['system','সিস্টেম অনুযায়ী','ডিভাইসের থিমের সঙ্গে স্বয়ংক্রিয়ভাবে বদলাবে']],paths={light:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>',dark:'<path d="M20 13a8 8 0 0 1-9-9 8 8 0 1 0 9 9Z"/>',system:'<rect x="3" y="3" width="18" height="14" rx="2"/><path d="M12 17v4M8 21h8"/>'};const dialog=featureDialog(featureText('থিম'),'<p class="theme-intro">আপনার পছন্দের থিম বাছুন</p><form class="theme-form">'+choices.map(([value,title,description])=>'<label class="theme-choice"><span class="theme-choice-icon"><svg viewBox="0 0 24 24" aria-hidden="true">'+paths[value]+'</svg></span><span class="theme-choice-copy"><strong>'+title+'</strong><small>'+description+'</small></span><input name="theme" type="radio" value="'+value+'"'+(current===value?' checked':'')+'></label>').join('')+'<button type="submit" class="primary">সংরক্ষণ করুন</button></form>');dialog.classList.add('theme-dialog');dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const theme=new FormData(event.target).get('theme');if(!['light','dark','system'].includes(theme))return;await commit(()=>{db.settings=db.settings||{};db.settings.theme=theme})}}

function reportExpenseCaption(){return reportFilter==='expenses'?'<p class="report-category-caption"><span>খরচের খাত</span>: <strong>'+esc(featureText(expenseCategories[reportExpenseCategory]||'সব খরচের খাত'))+'</strong></p>':''}
